#include <unistd.h>

void ft_rev_int_tab(int *tab, int size)
{
	int i = 0;
	int tmp;
	while (i < size / 2)
	{
		tmp = tab[i];
		tab[i] = tab[size - 1 - i];
		tab[size - 1 - i] = tmp;
		i++;
	}
}

void ft_putnbr(int nb)
{
	char c;
	if (nb == -2147483648) { write(1, "-2147483648", 11); return; }
	if (nb < 0) { write(1, "-", 1); nb = -nb; }
	if (nb >= 10) ft_putnbr(nb / 10);
	c = nb % 10 + '0';
	write(1, &c, 1);
}

int main(void)
{
	int tab[5] = {1, 2, 3, 4, 5};
	int i = 0;
	ft_rev_int_tab(tab, 5);
	while (i < 5)
	{
		ft_putnbr(tab[i]);
		i++;
	}
	return (0);
}

ex08.starterCode:
#include <unistd.h>

void ft_sort_int_tab(int *tab, int size)
{
	int i = 0, j, tmp;
	while (i < size - 1)
	{
		j = 0;
		while (j < size - 1 - i)
		{
			if (tab[j] > tab[j + 1])
			{
				tmp = tab[j];
				tab[j] = tab[j + 1];
				tab[j + 1] = tmp;
			}
			j++;
		}
		i++;
	}
}

void ft_putnbr(int nb)
{
	char c;
	if (nb == -2147483648) { write(1, "-2147483648", 11); return; }
	if (nb < 0) { write(1, "-", 1); nb = -nb; }
	if (nb >= 10) ft_putnbr(nb / 10);
	c = nb % 10 + '0';
	write(1, &c, 1);
}

int main(void)
{
	int tab[5] = {3, 1, 5, 2, 4};
	int i = 0;
	ft_sort_int_tab(tab, 5);
	while (i < 5)
	{
		ft_putnbr(tab[i]);
		i++;
	}
	return (0);
}

