#include <unistd.h>

char *ft_strcpy(char *dest, char *src)
{
	int i = 0;
	while (src[i])
	{
		dest[i] = src[i];
		i++;
	}
	dest[i] = '\0';
	return (dest);
}

void ft_putstr(char *s) { while (*s) write(1, s++, 1); }

int main(void)
{
	char d[20];
	ft_strcpy(d, "Hello");
	ft_putstr(d);
	return (0);
}

