#include <unistd.h>

char *ft_strncpy(char *dest, char *src, unsigned int n)
{
	unsigned int i = 0;
	while (i < n && src[i])
	{
		dest[i] = src[i];
		i++;
	}
	while (i < n)
		dest[i++] = '\0';
	return (dest);
}

void ft_putstr(char *s) { while (*s) write(1, s++, 1); }

int main(void)
{
	char d[20];
	ft_strncpy(d, "Hello", 3);
	d[3] = '\0';
	ft_putstr(d);
	return (0);
}
